style.css:
@-moz-document domain("roblox.com") {
body {
    background-image: url(https://www.wallsauce.com/images/2022-02/blobid1644236268142.jpgabove); /* Reemplaza con la URL de tu imagen */
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    background-attachment: fixed; /* Fija la imagen al desplazarse */
  }

  /* Opcional: Ajustar la transparencia del fondo de las cajas */
  .container, .game-home-page, .content {
    background: rgba(0, 0, 0, 0.7) !important; /* Fondo oscuro semitransparente */
    border-radius: 10px;
  }

  /* Opcional: Cambiar color del texto para mejor visibilidad */
  .text, h1, h2, h3, p, a {
    color: white !important;
  }
}
